// From app/actions/daep/attendance.ts
import { createServerClient } from '@/lib/supabase/server';
import { currentUser } from '@clerk/nextjs/server';

async function getTenantId(): Promise<string> {
  const user = await currentUser();
  if (!user) throw new Error('Unauthorized');

  const supabase = await createServerClient();
  const { data: profile, error } = await supabase
    .from('user_profiles')
    .select('tenant_id, active_tenant_id')
    .eq('id', user.id)
    .single();

  if (error || !profile) {
    throw new Error('User profile not found');
  }

  const effectiveTenantId = profile.active_tenant_id || profile.tenant_id;
  if (!effectiveTenantId) {
    throw new Error('No tenant assigned');
  }

  return effectiveTenantId;
}

const NAV_ITEMS: NavItem[] = [
  { href: '/daep', label: 'Dashboard', icon: LayoutDashboard, exact: true },
  { href: '/daep/rooms', label: 'Room Rosters', icon: Building2 },
  // ... other items
];

// Role-based filtering
const APPROVAL_ADMIN_ROLES = ['super_admin', 'district_admin', 'daep_admin_l1'];
const RECONCILIATION_ROLES = ['super_admin', 'district_admin', 'daep_admin_l1', 'daep_admin_l2'];

export default function DAEPMainLayout({ children }: { children: React.ReactNode }) {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  return (
    <div className="flex h-screen bg-[rgb(var(--daep-background))]">
      <DAEPSidebar collapsed={sidebarCollapsed} onCollapsedChange={setSidebarCollapsed} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <DAEPHeader onMenuClick={() => setMobileMenuOpen(!mobileMenuOpen)} />
        <main className="flex-1 overflow-auto p-4 md:p-6">
          {children}
        </main>
      </div>
    </div>
  );
}

